  function rosette(cx, cy, r, fill, n) {
    var s = r / 15, g = "", k = n || 9, step = 160 / (k - 1);
    for (var i = 0; i < k; i++) g += '<path d="M0 0q-2.4 -9 0 -15q2.4 6 0 15Z" fill="' + fill + '" transform="translate(' + cx + " " + cy + ") rotate(" + (-80 + i * step).toFixed(1) + ") scale(" + s.toFixed(2) + ')"/>';
