  city += '<path d="M1260 0q-6-26 10-30q14 4 10 30Z" fill="#55836D"/></g>';
  var plant = '<g transform="translate(1000 594)"><path d="M-30 6V-22l20-12v12l20-12v12l20-12V6Z" fill="#244550"/><rect x="-26" y="-6" width="8" height="8" fill="#DCB253"/><rect x="-6" y="-6" width="8" height="8" fill="#DCB253"/><rect x="14" y="-6" width="8" height="8" fill="#DCB253"/></g>';
  var truck = '<g id="truck"><rect x="-26" y="-20" width="34" height="18" rx="2" fill="#B96E4E"/><path d="M8 -15h10l6 7v6H8Z" fill="#0A2632"/><circle cx="-16" cy="0" r="4.5" fill="#0A2632"/><circle cx="14" cy="0" r="4.5" fill="#0A2632"/><path d="M-21 -15v8M-15 -15v8M-9 -15v8M-3 -15v8" stroke="#EEE8DE" stroke-width="2.4" stroke-linecap="round"/></g>';

  function label(x, y, txt, anchor, color, size) { return '<text class="svg-label lbl" data-fs="' + (size || 17) + '" data-x="' + x + '" x="' + x + '" y="' + y + '" font-size="' + (size || 17) + '" fill="' + (color || "#0A2632") + '" text-anchor="' + (anchor || "start") + '" dominant-baseline="middle">' + txt + "</text>"; }
  function leader(x1, y1, x2, y2, c) { return '<path d="M' + x1 + " " + y1 + "L" + x2 + " " + y2 + '" stroke="' + (c || "#0A2632") + '" stroke-width="1" fill="none"/><circle cx="' + x1 + '" cy="' + y1 + '" r="2.5" fill="' + (c || "#0A2632") + '"/>'; }

  svg.innerHTML =
    '<defs><clipPath id="cut"><path d="' + ground + '"/></clipPath>' +
    '<linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E4DCCD"/><stop offset=".6" stop-color="#EEE8DE"/></linearGradient>' +
    '<linearGradient id="trail" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#81A9AF"/><stop offset="1" stop-color="#C9E2E5"/></linearGradient></defs>' +
    '<rect width="1600" height="900" fill="url(#skyg)"/>' +
    '<g opacity=".55"><path class="fog" d="M40 150h380M90 175h300M330 128h260" stroke="#81A9AF" stroke-width="10" stroke-linecap="round" fill="none"/><path class="fog b" d="M150 110h220M420 160h200M0 210h160" stroke="#81A9AF" stroke-width="7" stroke-linecap="round" fill="none"/></g>' +
    '<g fill="none" stroke="#4C7B84" stroke-width="2"><path d="M170 66c-6-20 20-30 34-18 8-18 40-16 44 6 20-2 26 22 10 28H176c-12 0-14-10-6-16Z" fill="#EEE8DE"/><path d="M330 92c-5-16 16-24 27-14 7-14 32-13 35 5 16-2 21 18 8 22H335c-10 0-11-8-5-13Z" fill="#EEE8DE"/></g>' +
    rain +
    '<g clip-path="url(#cut)">' +
      '<rect width="1600" height="900" fill="#0A2632"/>' +
      '<path d="' + band(0, 560) + '" fill="#4C7B84"/>' +
      '<g stroke="#244550" stroke-width="1.6" fill="none" opacity=".75">' + fissures + "</g>" +
      '<path d="' + aquifer + '" fill="#81A9AF" opacity=".9"/>' +
      '<path d="' + clay + '" fill="#B96E4E"/>' +
      '<path d="' + band(0, 72) + '" fill="#4C6755"/>' +
      '<g fill="#C3D5A0" opacity=".45">' + pores + "</g>" +
      '<path d="' + band(0, 14) + '" fill="#92B992"/>' +
    "</g>" +
    '<path d="' + smooth(SURF) + '" fill="none" stroke="#0A2632" stroke-width="2"/>' +
    '<path d="' + clayTop + '" fill="none" stroke="#0A2632" stroke-width="1" stroke-dasharray="3 5" opacity=".0"/>' +
    frai + city +
    '<path id="drop-path" d="' + drop + '" fill="none" stroke="none"/>' +
    '<path id="drop-trail" d="' + drop + '" fill="none" stroke="url(#trail)" stroke-width="5" stroke-linecap="round"/>' + plant +
    '<g id="truck-wrap" transform="translate(1180 674)">' + truck + "</g>" +
    // cotas
    '<g stroke="#0A2632" stroke-width="1" stroke-dasharray="2 5" opacity=".7"><path d="M884 518H1600"/></g>' +
    label(1150, 506, "COTA 2.900 M", "start", "#0A2632", 18) + label(1438, 566, "BOGOTÁ · 2.600 M", "middle", "#0A2632", 20) +
    // rótulos
    leader(470, 140, 520, 104) + label(526, 104, "NIEBLA Y LLUVIA HORIZONTAL") +
    leader(440, 220, 520, 182) + label(526, 182, "FRAILEJONES · PÁRAMO") +
    leader(380, 272, 300, 330, "#EEE8DE") + label(150, 338, "TURBA · ESPONJA", "start", "#EEE8DE") +
    leader(520, 420, 600, 420, "#EEE8DE") + label(606, 426, "ROCA FILTRANTE", "start", "#EEE8DE") +
    leader(640, 545, 700, 610, "#EEE8DE") + label(706, 618, "GREDA · NO DEJA PASAR EL AGUA", "start", "#EEE8DE") +
    leader(884, 516, 930, 452) + label(936, 452, "MANANTIAL", "start", "#0A2632", 22) +
    leader(1000, 562, 1060, 600) + label(1066, 600, "PLANTA · GUASCA") +
    '<circle cx="884" cy="516" r="9" fill="none" stroke="#0A2632" stroke-width="2"/>' +
    '<g id="drop"><circle r="14" fill="#81A9AF" opacity=".28"/><path d="M0 -11C0 -11 -7 -2 -7 3A7 6.6 0 0 0 7 3C7 -2 0 -11 0 -11Z" fill="#81A9AF" stroke="#0A2632" stroke-width="1.8"/></g>';

  var path = document.getElementById("drop-path"), trail = document.getElementById("drop-trail"), dropEl = document.getElementById("drop"), truckWrap = document.getElementById("truck-wrap");
  var L = path.getTotalLength(), lbls = svg.querySelectorAll(".lbl");
  trail.style.strokeDasharray = L; trail.style.strokeDashoffset = L;
  function tAt(px, py) { var best = 0, bd = 1e9; for (var i = 0; i <= 600; i++) { var l = L * i / 600, p = path.getPointAtLength(l), d = (p.x - px) * (p.x - px) + (p.y - py) * (p.y - py); if (d < bd) { bd = d; best = l; } } return best; }
  var K = [
    { vb: [0, 0, 1600, 900], t: 0, fx: 800 },
    { vb: [0, 20, 680, 383], t: tAt(276, 170), fx: 276 },
    { vb: [0, 150, 600, 338], t: tAt(312, 292), fx: 312 },
    { vb: [60, 360, 680, 383], t: tAt(450, 556), fx: 450 },
    { vb: [500, 340, 680, 383], t: tAt(884, 514), fx: 884 },
    { vb: [660, 420, 620, 349], t: tAt(1010, 596), fx: 1010 },
    { vb: [820, 400, 780, 439], t: L, fx: 1390 }
  ];
  var ALT = function (y) { return 2900 + (518 - y) * (300 / 162); };
  // altímetro
  var ticks = document.getElementById("alti-ticks"), mark = document.getElementById("alti-mark"), read = document.getElementById("alti-read");
  var A_TOP = 3700, A_BOT = 2600;
  for (var a = A_TOP; a >= A_BOT; a -= 100) {
    var tk = document.createElement("div"); tk.className = "alti__tick" + (a % 500 === 0 ? " major" : "");
    tk.style.top = ((A_TOP - a) / (A_TOP - A_BOT) * 100) + "%";
    if (a % 500 === 0 || a === 2900) tk.innerHTML = "<span>" + AS.NUM(a) + "</span>";
    ticks.appendChild(tk);
  }
  var tickEls = Array.prototype.map.call(ticks.children, function (el) { return { el: el, p: parseFloat(el.style.top) / 100 }; });
  var panels = document.querySelectorAll(".legend__panel"), bars = document.querySelectorAll(".legend__ticks i");
  var journey = document.getElementById("viaje"), lastStage = null;
  function ease(x) { return x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; }
  function renderJourney() {
    var r = journey.getBoundingClientRect(), total = journey.offsetHeight - window.innerHeight;
    var p = Math.min(1, Math.max(0, -r.top / Math.max(1, total)));
    if (reduced) p = 1;
    var slot = p * (K.length - 1), i = Math.min(K.length - 2, Math.floor(slot)), f = slot - i;
    var e = ease(Math.min(1, Math.max(0, (f - .28) / .72)));
    var a0 = K[i], a1 = K[i + 1], vb = [];
    for (var k = 0; k < 4; k++) vb.push(a0.vb[k] + (a1.vb[k] - a0.vb[k]) * e);
    if (window.innerWidth < 768) { vb[0] = a0.fx + (a1.fx - a0.fx) * e - vb[2] / 2; vb[1] += vb[3] * .1; }
    svg.setAttribute("viewBox", vb.map(function (v) { return v.toFixed(1); }).join(" "));
    var sc = Math.max(svg.clientWidth / vb[2], svg.clientHeight / vb[3]) || 1, base = window.innerWidth < 768 ? 12 : 16;
    var visW = svg.clientWidth / sc, cx = vb[0] + vb[2] / 2, x0 = cx - visW / 2 + 8 / sc, x1 = cx + visW / 2 - (window.innerWidth >= 768 ? 140 : 8) / sc;
    for (var li = 0; li < lbls.length; li++) {
      var lb = lbls[li]; lb.setAttribute("font-size", (+lb.getAttribute("data-fs") / 17 * base / sc).toFixed(2));
      lb.setAttribute("x", lb.getAttribute("data-x"));
      var bb = lb.getBBox();
      if (bb.width < visW && bb.x < cx + visW / 2 && bb.x + bb.width > x0) { var dx = bb.x < x0 ? x0 - bb.x : (bb.x + bb.width > x1 ? x1 - bb.x - bb.width : 0); if (dx) lb.setAttribute("x", (+lb.getAttribute("data-x") + dx).toFixed(1)); }
    }
    var t = a0.t + (a1.t - a0.t) * e, pt = path.getPointAtLength(t);
    dropEl.setAttribute("transform", "translate(" + pt.x.toFixed(1) + " " + pt.y.toFixed(1) + ")");
    trail.style.strokeDashoffset = (L - t).toFixed(1);
    var tp = Math.max(0, (t - K[5].t) / (L - K[5].t));
    truckWrap.setAttribute("transform", "translate(" + (1180 + tp * 210).toFixed(1) + " 674)");
    var alt = Math.max(A_BOT, Math.min(A_TOP, ALT(pt.y)));
    mark.style.top = ((A_TOP - alt) / (A_TOP - A_BOT) * 100) + "%";
    read.style.top = mark.style.top;
    read.textContent = AS.NUM(Math.round(alt / 10) * 10) + " M";
    var mp = (A_TOP - alt) / (A_TOP - A_BOT);
    tickEls.forEach(function (te) { te.el.classList.toggle("near", Math.abs(te.p - mp) < .06); });
    var stage = Math.round(slot) - 1;
    if (stage !== lastStage) {
      lastStage = stage;
      panels.forEach(function (pn) { pn.classList.toggle("is-on", +pn.getAttribute("data-stage") === stage); });
      bars.forEach(function (b, bi) { b.classList.toggle("on", bi <= stage); });
    }
  }
  var raf = 0;
  function onScroll() { if (!raf) raf = requestAnimationFrame(function () { raf = 0; renderJourney(); }); }
  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onScroll);
  renderJourney();

  /* ---------- Calculadora ---------- */
  var st = { tipo: "casa", n: 4 };
  try { var saved = JSON.parse(localStorage.getItem("as:calc") || "null"); if (saved && saved.tipo) st = saved; } catch (e) {}
  var WHO = { casa: "Personas en la casa", oficina: "Personas en la oficina", restaurante: "Puestos en el restaurante" };
  var MAXN = { casa: 12, oficina: 80, restaurante: 200 };
  var jugSvg = '<svg class="jug" viewBox="0 0 22 34" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M8 1.5h6v4H8z" fill="currentColor"/><path d="M5 7.5c0-1.2 1-2 2.2-2h7.6c1.2 0 2.2.8 2.2 2v.5c2.4.8 4 2.8 4 5.2V29c0 2-1.6 3.5-3.6 3.5H4.6C2.6 32.5 1 31 1 29V13.2c0-2.4 1.6-4.4 4-5.2Z"/><path d="M1.5 16h19M1.5 25h19" opacity=".6"/></svg>';
  var forestMine = document.getElementById("forest-mine"), mine = 0;
  function renderCalc() {
    document.querySelectorAll("#calc [data-tipo]").forEach(function (b) { b.setAttribute("aria-pressed", String(b.getAttribute("data-tipo") === st.tipo)); });
    document.getElementById("calc-who").textContent = WHO[st.tipo];
    document.getElementById("calc-n").textContent = st.n;
    var jugs = AS.sugeridos(st.tipo, st.n), pl = AS.plan(jugs), month = jugs * pl.precio, trees = Math.max(1, Math.round(jugs * 12 / AS.POR_ARBOL));
    document.getElementById("calc-jugs").textContent = jugs;
    document.getElementById("calc-liters").textContent = AS.NUM(jugs * AS.LITROS) + " litros";
    document.getElementById("calc-plan").textContent = pl.nombre;
    document.getElementById("calc-unit").textContent = AS.COP(pl.precio);
    document.getElementById("calc-month").textContent = AS.COP(month);
    document.getElementById("calc-trees").textContent = trees;
    var viz = document.getElementById("calc-jugviz"), show = Math.min(jugs, 30), cur = viz.children.length;
    if (cur > show) { while (viz.children.length > show) viz.removeChild(viz.lastChild); }
    else { for (var j = cur; j < show; j++) viz.insertAdjacentHTML("beforeend", jugSvg); }
    if (jugs > 30 && !viz.querySelector(".more")) viz.insertAdjacentHTML("beforeend", '<span class="more label self-center text-[var(--sky)]">+' + (jugs - 30) + "</span>");
    var more = viz.querySelector(".more"); if (more) { if (jugs > 30) { more.textContent = "+" + (jugs - 30); viz.appendChild(more); } else more.remove(); }
    document.getElementById("calc-go").href = "suscripcion.html?tipo=" + st.tipo + "&personas=" + st.n;
    document.querySelectorAll(".stratum").forEach(function (s) { s.setAttribute("data-active", String(s.getAttribute("data-plan") === pl.id)); });
    forestMine.textContent = trees + (trees === 1 ? " árbol" : " árboles");
    mine = trees; paintMine();
    try { localStorage.setItem("as:calc", JSON.stringify(st)); } catch (e) {}
  }
  document.querySelectorAll("#calc [data-tipo]").forEach(function (b) { b.addEventListener("click", function () {
    st.tipo = b.getAttribute("data-tipo");
    st.n = st.tipo === "casa" ? 4 : st.tipo === "oficina" ? 12 : 30; renderCalc(); }); });
  document.querySelectorAll("#calc [data-step]").forEach(function (b) { b.addEventListener("click", function () {
    var step = st.tipo === "casa" ? 1 : st.tipo === "oficina" ? 2 : 5;
    st.n = Math.min(MAXN[st.tipo], Math.max(1, st.n + step * +b.getAttribute("data-step"))); renderCalc(); }); });

  /* ---------- Bosque ---------- */
  var forest = document.getElementById("forest");
  var FILL = ["#55836D", "#92B992", "#4C6755", "#81A9AF"];
  var fh = "", count = 0, items = [];
  for (var x = 16; x < 1590; x += 24 + (count * 7) % 15) {
    items.push({ x: x, s: .85 + ((count * 13) % 8) / 10, type: (count * 5 + (count >> 2)) % 3 }); count++;
  }
  items.forEach(function (it, idx) {
    var sc = it.type === 0 ? it.s * 1.15 : it.type === 1 ? it.s : it.s * .95;
    fh += '<g transform="translate(' + it.x + ' 270) scale(' + sc.toFixed(2) + ')"><g class="tree" data-i="' + idx + '" style="--d:' + ((idx % 23) * .045).toFixed(2) + 's" fill="' + FILL[(idx * 3) % 4] + '">' + AS.tree(it.type, "inherit", "#4C6755") + "</g></g>";
  });
  forest.innerHTML = fh + '<g transform="translate(0 268)">' + AS.soil(1600, 32) + "</g>";
  var treeEls = forest.querySelectorAll(".tree");
  var order = Array.prototype.slice.call(treeEls).sort(function (a, b) { return ((+a.dataset.i * 37) % 71) - ((+b.dataset.i * 37) % 71); });
  function paintMine() {
    order.forEach(function (el, k) { var on = k < mine; el.style.fill = on ? "#43B02A" : ""; });
  }
  if ("IntersectionObserver" in window) {
    var fio = new IntersectionObserver(function (en) { en.forEach(function (e) { if (e.isIntersecting) { forest.classList.add("is-grown"); fio.disconnect(); } }); }, { threshold: .25 });
    fio.observe(forest);
  } else forest.classList.add("is-grown");

  /* contador 15.000 */
  var cnt = document.querySelector("[data-count]");
  if (cnt && !reduced && "IntersectionObserver" in window) {
    var target = +cnt.getAttribute("data-count");
    var cio = new IntersectionObserver(function (en) { en.forEach(function (e) { if (!e.isIntersecting) return; cio.disconnect();
      var t0 = performance.now(); (function tick(now) { var k = Math.min(1, (now - t0) / 1600), v = 1 - Math.pow(1 - k, 3); cnt.textContent = AS.NUM(target * v); if (k < 1) requestAnimationFrame(tick); })(t0); }); }, { threshold: .6 });
    cio.observe(cnt);
  }

  /* ---------- Tienda ---------- */
  var PRODUCTS = [
    { img: "data:image/webp;base64,", n: "Botellón 20 L", d: "Retornable. Base de la suscripción", p: "$83.000", note: "Primera compra, incluye $60.000 de depósito", tag: "Retornable" },
    { img: "data:image/webp;base64,", n: "Garrafa 5 L", d: "Agua mineral natural", p: "$14.000" },
    { img: "data:image/webp;base64,", n: "Vidrio 477 ml", d: "Paquete de 4. Retornable", p: "$16.800", tag: "Retornable" },
    { img: "data:image/webp;base64,", n: "Con gas 500 ml", d: "PET, paquete de 6", p: "$21.000" },
    { img: "data:image/webp;base64,", n: "Natural 500 ml", d: "PET, paquete de 6", p: "$18.000" },
    { img: "data:image/webp;base64,", n: "Lata 310 ml", d: "Caja de 24. La primera agua en lata del país", p: "$81.600" }
  ];
  document.getElementById("shelf").innerHTML = PRODUCTS.map(function (p, i) {
    return '<li class="product" data-reveal style="--d:' + (i * .06).toFixed(2) + 's">' +
      '<div class="product__img"><img src="' + p.img + '" alt="' + p.n + '" loading="lazy"></div>' +
      '<p class="product__name">' + p.n + "</p>" +
      '<p class="text-[.95rem] muted mt-1 min-h-[2.8em]">' + p.d + "</p>" +
      '<p class="product__price mt-2">' + p.p + "</p>" +
      (p.note ? '<p class="legal text-[#4a5f66]">' + p.note + "</p>" : "") +
      '<a class="link-arrow mt-3 text-[1.1rem]" href="' + AS.wa("Hola, quiero pedir " + p.n + " de Agua Siembra") + '" target="_blank" rel="noopener">Pedir <svg width="12" height="12" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M1 7h12M7.5 1.5L13 7l-5.5 5.5"/></svg></a>' +
      "</li>";
  }).join("");
  document.querySelectorAll("#shelf [data-reveal]").forEach(function (el) {
    if ("IntersectionObserver" in window) { var o = new IntersectionObserver(function (en) { if (en[0].isIntersecting) { el.classList.add("is-in"); o.disconnect(); } }, { threshold: .05 }); o.observe(el); } else el.classList.add("is-in");
  });

  /* ---------- Newsletter ---------- */
  document.getElementById("news").addEventListener("submit", function (e) {
    e.preventDefault();
    var inp = document.getElementById("news-mail"), out = document.getElementById("news-out");
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(inp.value.trim())) { inp.setAttribute("aria-invalid", "true"); out.className = "err text-[.95rem] min-h-[1.5em]"; out.textContent = "Revisa el correo: parece incompleto."; inp.focus(); return; }
    inp.removeAttribute("aria-invalid"); out.className = "text-[.95rem] min-h-[1.5em]"; out.textContent = "Listo. Te escribimos cuando sembremos el próximo lote."; inp.value = "";
  });

  renderCalc();
});
</script>
</body>
</html>
